package com.fincore.fincore.account; import java.util.List; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.fincore.fincore.security.AuthenticatedUser; @RestController @RequestMapping("/api/v1/accounts") public class AccountController {private final AccountService service;public AccountController(AccountService s){service=s;}@PostMapping ResponseEntity<AccountResponse> create(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CreateAccountRequest r){return ResponseEntity.status(201).body(service.create(u.id(),r));}@GetMapping List<AccountResponse> all(@AuthenticationPrincipal AuthenticatedUser u){return service.all(u.id());}@GetMapping("/{id}") AccountResponse one(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id){return service.one(u.id(),id);}@PostMapping("/transfer") @ResponseStatus(HttpStatus.NO_CONTENT) void transfer(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody TransferRequest r){service.transfer(u.id(),r);}}
